solutionCode:
set rows {}
foreach filename [glob -nocomplain -directory ./reports *.timing.reg2reg.rpt] {
    set f [open $filename r]
    set text [read $f]
    close $f
    if {![regexp -nocase {slack\s+\([^)]*\)\s+([+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?)} $text -> slack]} {
        puts stderr "WARNING: no slack in $filename"
        continue
    }
    lappend rows [list $slack $filename]
}
foreach row [lsort -real -index 0 $rows] {
    lassign $row slack filename
    puts [format "% .6g  %s" $slack $filename]
}
